-- ===================== Helper Functions (fn*) =====================

CREATE OR REPLACE FUNCTION __mj_bizappscommon."fnOrganizationParentID_GetRootID"
(
    p_RecordID UUID,
    p_ParentID UUID
)
RETURNS TABLE("RootID" UUID)
LANGUAGE sql
AS $fn$
    WITH RECURSIVE CTE_RootParent AS (
        -- Anchor: Start from p_ParentID if not null, otherwise start from p_RecordID
        SELECT
            "ID",
            "ParentID",
            "ID" AS "RootParentID",
            0 AS "Depth"
        FROM
            __mj_bizappscommon."Organization"
        WHERE
            "ID" = COALESCE(p_ParentID, p_RecordID)

        UNION ALL

        -- Recursive: Keep going up the hierarchy until ParentID is NULL
        -- Includes depth counter to prevent infinite loops from circular references
        SELECT
            c."ID",
            c."ParentID",
            c."ID" AS "RootParentID",
            p."Depth" + 1 AS "Depth"
        FROM
            __mj_bizappscommon."Organization" c
        INNER JOIN
            CTE_RootParent p ON c."ID" = p."ParentID"
        WHERE
            p."Depth" < 100  -- Prevent infinite loops, max 100 levels
    )
    SELECT "RootParentID" AS "RootID"
    FROM
        CTE_RootParent
    WHERE
        "ParentID" IS NULL
    ORDER BY
        "RootParentID"
    LIMIT 1
$fn$;


-- fn_organization_parent_id_get_root_id: CodeGen's canonical recursive root lookup (scalar form).
-- Coexists with the converter-emitted fnOrganizationParentID_GetRootID above; the canonical
-- vwOrganizations below references this one, matching what CodeGen maintains.
CREATE OR REPLACE FUNCTION __mj_bizappscommon.fn_organization_parent_id_get_root_id(p_record_id uuid, p_parent_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE
AS $function$
    WITH RECURSIVE cte_root_parent AS (
        -- Anchor: Start from p_parent_id if not null, otherwise start from p_record_id
        SELECT
            "ID",
            "ParentID",
            "ID" AS root_parent_id,
            0 AS depth
        FROM
            __mj_bizappscommon."Organization"
        WHERE
            "ID" = COALESCE(p_parent_id, p_record_id)

        UNION ALL

        -- Recursive: Keep going up the hierarchy
        SELECT
            c."ID",
            c."ParentID",
            c."ID" AS root_parent_id,
            p.depth + 1 AS depth
        FROM
            __mj_bizappscommon."Organization" c
        INNER JOIN
            cte_root_parent p ON c."ID" = p."ParentID"
        WHERE
            p.depth < 100  -- Prevent infinite loops
    )
    SELECT root_parent_id
    FROM cte_root_parent
    WHERE "ParentID" IS NULL
    ORDER BY root_parent_id
    LIMIT 1;
$function$;

