  p_ID_3870d961 := '964C05C1-C947-467B-97B9-A7495BDDB7B0';
  IF EXISTS (
    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = '__mj_BizAppsCommon' AND p.proname = 'spUpdateAddressType'
       AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype
  ) THEN
    PERFORM __mj_BizAppsCommon."spUpdateAddressType"(p_data := jsonb_build_object(
